/**
 * SVG assets of the Astro dock panels, one JSX component per icon, vendored
 * from:
 *
 * - astro@7.1.2 (MIT, https://github.com/withastro/astro):
 *   packages/astro/src/runtime/client/dev-toolbar/ui-library/icons.ts
 * - @vitejs/devtools-vite (MIT, https://github.com/vitejs/devtools):
 *   dist/public/favicon.svg (the solid Vite bolt base path)
 * - Phosphor Icons (MIT, https://phosphoricons.com):
 *   `function`, via the Iconify API
 * - SVG Logos (CC0, https://github.com/gilbarbara/logos):
 *   the framework logomarks, via the Iconify API (`logos:react`,
 *   `logos:preact`, `logos:solidjs-icon`, `logos:svelte-icon`, `logos:vue`)
 *
 * Icons are hidden from the accessibility tree because their surrounding UI
 * provides text. Callers control their size through CSS classes.
 */

interface IconProps {
  class?: string;
}

/** Shared component type for icons. */
export type IconComponent = FunctionComponent<IconProps>;

